document.addEventListener("show.bs.collapse", (event) => {
    let elem = event.target
    if (elem.classList.contains("accordion-collapse")) {
        location.hash = elem.id
    }
})

// Collapse all children accordions when the parent is closed
document.addEventListener("hidden.bs.collapse", (event) => {
    event.target.querySelectorAll('.accordion-button:not(.collapsed)').forEach(element => {
        element.click()
    })
})

// region Anchor On Load
function setAnchor(anchorLinkDestination) {
    history.pushState({}, '', document.documentURI + anchorLinkDestination);
}

async function anchorOnLoad() {
    // Added to onload on body, checks if there is an anchor link and if so, expand
    let linkTarget = decodeURIComponent(window.location.hash.split("?")[0].split("&")[0]);
    let accordion_header = document.getElementById("accordion-" + linkTarget.substring(1));
    let accordion_item = document.getElementById(linkTarget.substring(1));
    let item_opened = listenForEvent(accordion_item, "shown.bs.collapse")
    open_nested_accordion(accordion_header, accordion_item)
    await item_opened
    accordion_header.scrollIntoView({behavior: "smooth"})
    accordion_header.focus({preventScroll: true});
    accordion_header.classList.add("pulse")

    accordion_header.addEventListener("animationend", (event) => {
        event.target.classList.remove("pulse")
        event.target.removeEventListener("animationend", (event) => {})
    })

}

function open_nested_accordion(accordion_header, accordion_item, parents = []) {
    let parent_item = accordion_item.parentElement.closest(".accordion-collapse:not(.show)")
    if (parent_item) {
        let parent_header = document.getElementById("accordion-" + parent_item.id)
        parents.push(parent_item)
        open_nested_accordion(parent_header, parent_item)
    }
    [...parents, accordion_item].map(item => new bootstrap.Collapse(item, {toggle: true}))
}

function listenForEvent(item, event) {
    return new Promise((resolve) => {
        const listener = () => {
            item.removeEventListener(event, listener);
            resolve();
        }
        item.addEventListener(event, listener);
    })
}

// endregion